import java.util.*;

class Solution {
  private List<Integer> prices;
  private List<List<Integer>> specials;
  private Map<String, Integer> memo;

  public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
    prices = price;
    specials = special;
    memo = new HashMap<>();
    return dfs(needs);
  }

  private int dfs(List<Integer> needs) {
    String key = needs.toString();
    if (memo.containsKey(key)) return memo.get(key);
    int best = 0;
    for (int i = 0; i < needs.size(); i++) best += needs.get(i) * prices.get(i);
    for (List<Integer> offer : specials) {
      List<Integer> next = new ArrayList<>(needs);
      boolean usable = true;
      for (int i = 0; i < needs.size(); i++) {
        if (offer.get(i) > next.get(i)) {
          usable = false;
          break;
        }
        next.set(i, next.get(i) - offer.get(i));
      }
      if (usable) best = Math.min(best, offer.get(needs.size()) + dfs(next));
    }
    memo.put(key, best);
    return best;
  }
}
